-- Ticket 11: deterministic financial normalization, calculations, models,
-- scenarios, analysis drafts, and typed validation lineage.
-- Versioned objects are append-only. Runtime access is forced-RLS and writes
-- happen only through scoped SECURITY DEFINER command functions.

CREATE SCHEMA IF NOT EXISTS analysis;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_analysis_owner') THEN
    CREATE ROLE app_analysis_owner NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE BYPASSRLS;
  ELSE
    ALTER ROLE app_analysis_owner NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE BYPASSRLS;
  END IF;
END $$;

GRANT app_analysis_owner TO postgres;
GRANT USAGE ON SCHEMA app, knowledge, analysis, source TO app_analysis_owner;
GRANT USAGE ON SCHEMA extensions TO app_analysis_owner;
GRANT EXECUTE ON FUNCTION extensions.digest(text,text), extensions.digest(bytea,text) TO app_analysis_owner;
GRANT EXECUTE ON FUNCTION app.policy_account_id(), app.policy_actor_id(), app.policy_deal_id(), app.record_audit(text,text,text,text,text,text) TO app_analysis_owner;
GRANT SELECT ON app.account, app.actor, app.account_actor, app.deal, app.deal_workspace TO app_analysis_owner;
GRANT SELECT ON knowledge.fact, knowledge.assumption, knowledge.human_decision, knowledge.evidence TO app_analysis_owner;
GRANT SELECT ON source.source_fragment TO app_analysis_owner;

-- Register the four analysis task packages in the existing AI control plane.
DO $$ DECLARE c record; BEGIN
  FOR c IN SELECT conname FROM pg_constraint WHERE conrelid='ai.task_definition'::regclass AND contype='c' AND pg_get_constraintdef(oid) ILIKE '%task_definition%' LOOP EXECUTE format('ALTER TABLE ai.task_definition DROP CONSTRAINT %I', c.conname); END LOOP;
  ALTER TABLE ai.task_definition ADD CONSTRAINT ai_task_definition_ticket11_check CHECK (task_definition IN ('source_claim_extraction','claim_evidence_linking','material_source_conflict_analysis','contract_repair','financial_semantic_extraction','financial_normalization_mapping','sell_side_analysis_draft','valuation_commentary_draft'));
  FOR c IN SELECT conname FROM pg_constraint WHERE conrelid='ai.proposal'::regclass AND contype='c' AND pg_get_constraintdef(oid) ILIKE '%proposal_kind%' LOOP EXECUTE format('ALTER TABLE ai.proposal DROP CONSTRAINT %I', c.conname); END LOOP;
  ALTER TABLE ai.proposal ADD CONSTRAINT ai_proposal_kind_ticket11_check CHECK (proposal_kind IN ('claim','evidence_link','conflict','normalized_value_proposal','mapping_proposal','analysis_draft'));
END $$;
